const items = $input.all();
const normalizedItems = [];

function parseShorthand(text) {
  const result = {
    prompt: '',
    brand_name: '',
    brand_domains: [],
    competitors: [],
    target_llms: ['openai', 'gemini'],
    search_enabled: true
  };
  if (!text || typeof text !== 'string') return result;

  const lines = text.split(/[\n|]/);
  for (const line of lines) {
    const colonIdx = line.indexOf(':');
    if (colonIdx === -1) {
      if (!result.prompt && line.trim()) result.prompt = line.trim();
      continue;
    }
    const key = line.slice(0, colonIdx).trim().toUpperCase();
    const val = line.slice(colonIdx + 1).trim();
    if (key === 'PROMPT') {
      result.prompt = val;
    } else if (key === 'BRAND') {
      result.brand_name = val;
    } else if (key === 'DOMAINS') {
      result.brand_domains = val.split(',').map(d => d.trim().toLowerCase()).filter(Boolean);
    } else if (key === 'COMPETITORS') {
      result.competitors = val.split(',').map(c => {
        const match = c.match(/^(.*?)(?:\s*\((.*?)\))?$/);
        return {
          name: match ? match[1].trim() : c.trim(),
          domain: match && match[2] ? match[2].trim().toLowerCase() : ''
        };
      }).filter(c => c.name);
    } else if (key === 'LLMS') {
      result.target_llms = val.split(',').map(l => l.trim().toLowerCase()).filter(Boolean);
    } else if (key === 'SEARCH') {
      result.search_enabled = val.toLowerCase() === 'true' || val === '1';
    }
  }
  return result;
}

function expandTargetLLMs(input, triggerSource) {
  if (!input || typeof input !== 'object') return [];
  const prompt = (input.prompt || '').trim();
  const brandName = (input.brand_name || '').trim();
  const brandDomains = Array.isArray(input.brand_domains) ? input.brand_domains.filter(Boolean) : [];
  const competitors = Array.isArray(input.competitors) ? input.competitors.filter(Boolean) : [];
  const searchEnabled = input.search_enabled !== undefined ? Boolean(input.search_enabled) : true;
  const targetLLMs = Array.isArray(input.target_llms) && input.target_llms.length > 0 ? input.target_llms.filter(Boolean) : ['openai', 'gemini'];
  const responseMode = input.response_mode || ((input.is_async === true || input.is_async === 'true') ? 'async' : (triggerSource === 'chat' ? 'sync' : (triggerSource === 'webhook' ? 'sync' : 'async')));
  const configId = input.config_id || null;
  const userId = input.user_id || null;
  const runId = input.run_id || ('run_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9));

  return targetLLMs.map(provider => {
    let model = 'gpt-4o';
    if (provider === 'anthropic') model = 'claude-3-5-sonnet-20241022';
    if (provider === 'gemini') model = 'gemini-1.5-flash';

    return {
      json: {
        run_id: runId,
        config_id: configId,
        user_id: userId,
        trigger_source: triggerSource,
        response_mode: responseMode,
        prompt,
        brand_name: brandName,
        brand_domains: brandDomains,
        competitors: competitors.map(c => {
          if (typeof c === 'string') return { name: c.trim(), domain: '' };
          if (c && typeof c === 'object') return { name: (c.name || c.competitor_name || '').trim(), domain: (c.domain || c.competitor_domain || '').trim().toLowerCase() };
          return null;
        }).filter(c => c && c.name),
        provider,
        selected_provider: provider,
        model,
        search_enabled: searchEnabled,
        locale: input.locale || 'de-DE',
        created_at: new Date().toISOString()
      }
    };
  });
}

for (const item of items) {
  let raw = item && item.json ? item.json : {};
  if (!raw || typeof raw !== 'object') raw = {};
  let triggerSource = 'webhook';
  let inputData = {};

  if (raw.chatInput !== undefined) {
    triggerSource = 'chat';
    const text = String(raw.chatInput).trim();
    if (text.startsWith('{') && text.endsWith('}')) {
      try {
        inputData = JSON.parse(text);
      } catch (e) {
        inputData = parseShorthand(text);
      }
    } else {
      inputData = parseShorthand(text);
    }
  } else if (raw.jobs && Array.isArray(raw.jobs)) {
    triggerSource = 'schedule_queue';
    for (const job of (raw.jobs || []).filter(Boolean)) {
      if (job && typeof job === 'object') {
        normalizedItems.push(...expandTargetLLMs(job, triggerSource));
      }
    }
    continue;
  } else if (raw.status === 'error' || raw.error) {
    continue;
  } else {
    inputData = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
    triggerSource = 'webhook';
  }

  normalizedItems.push(...expandTargetLLMs(inputData, triggerSource));
}

return normalizedItems;

